        self.assertEqual(run(['3', '1', '2']), {'n': 2, 'mean': 5.0, 'max': 6, 'ratio': 1.0})
    def test_case_01(self):
        self.assertEqual(run(['10', '0', '7', 'x']), {'n': 1, 'mean': 10.0, 'max': 10, 'ratio': 0.5})
    def test_case_02(self):
        self.assertEqual(run([' 5 ', '-2', '8']), {'n': 0, 'mean': 0.0, 'max': 0, 'ratio': 0.0})
    def test_case_03(self):
